def get_primes(n):
    if n < 2:
        return []
    primes = []
    i = 2
    while i * i <= n:
        if n % i == 0:
            primes.append(i)
            while n % i == 0:
                n //= i
        i += 1
    if n > 1:
        primes.append(n)
    return primes

def solve_cases():
    n, a = list(map(int, input().split('\n')), list(map(int, input().split())))
    total = sum(a)
    if total <= 1:
        return -1
    primes = get_primes(total)
    ans = None
    for p in primes:
        curr = 0
        cost = 0
        for x in a:
            curr += x
            cost += (curr % p)
        if ans is None:
            ans = cost
        else:
            ans = min(ans, cost)
    return ans

