            if node[1] == -1:
                leaves.append(node)
            else:
                non_leaves.append(node)

        dp = {}
        memo = {}

        def solve(u):
            if u in dp:
                return dp[u]

            # Determine if this node is a leaf or not
            is_leaf = nodes[u][1] == -1

            if is_leaf:
                dp[u] = nodes[u][0]
                return dp[u]

            l, r = nodes[u][1], nodes[u][2]

            left_val = solve(l)
            right_val = solve(r)

            # If both children have same number of operations available, they will be merged
            # Otherwise, we get min or max depending on turn

            dp[u] = left_val + right_val if left_val == right_val else max(left_val, right_val)
