class SegmentTree:
    def __init__(self, n, probs):
        self.n = n
        self.tree = [0] * segment_size
        self.build(1, 1, n, probs)

    def build(self, node, left, right, probs):
        if left == right:
            p = probs[left-1]
            return (p, 1 - p)
        mid = (left + right) // 2
        left_val = self.build(2 * node, left, mid, probs)
        right_val = self.build(2 * node + 1, mid + 1, right, probs)
        self.tree[node] = self.combine(left_val, right_val, probs)
        if mid + 1 < len(self.tree):
            self.tree[node] = (left_val[0] * right_val[0] + left_val[1] * right_val[0], 
                              left_val[1] * right_val[0] + left_val[0] * right_val[1])
        return self.tree[node]

    def combine(self, a, b, probs):
        pa, pb = a
        return (pa * pb + pb * pa, pb * pb + pa * pb)

    def set_value(self, idx, probs):
        self._set_value(1, 1, self.n, idx, probs)

    def _set_value(self, node, l, r, idx, probs):
        if l == r:
            self.tree[node] = (probs[0], probs[1])
            return
        mid = (l + r) // 2
        if idx <= mid:
            self._set_value(2 * node, l, mid, idx, probs)
        else:
            self._set_value(2 * node + 1, mid + 1, r, idx, probs)
        self.tree[node] = self.combine(self.tree[2 * node], self.tree[2 * node + 1], probs)

