    # For LEFT: b is in left subtree of a -> in-order position of b < in-order position of a's left child < in-order position of a
    # But we don't know the exact positions

    # Key insight: Node 1 is root (pre-order 1)
    # If we assign a label L to each node as its in-order position
    # LEFT constraint: L[b] must come before L[a] (b in left subtree)
    # RIGHT constraint: L[b] must come after L[a] (b in right subtree)

    # Build graph with partial order constraints
    graph = {i: [] for i in range(1, n + 1)}
    reverse_graph = {i: [] for i in range(1, n + 1)}

    for a, b, direction in constraints:
        if direction == 'LEFT':
            graph[b].append(a)  # b must come before a
            reverse_graph[a].append(b)
        else:  # RIGHT
            graph[a].append(b)  # a must come before b
            reverse_graph[b].append(a)

    # Check for cycles (IMPOSSIBLE)
    visited = set()
    rec_stack = set()

    def has_cycle(node):
        visited.add(node)
        rec_stack.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if has_cycle(neighbor):
                    return True
            elif neighbor in rec_stack:
                return True
        rec_stack.remove(node)
        return False

    if has_cycle(1):
        return 'IMPOSSIBLE\n'

    # Try to build in-order traversal
    # Use topological sort
    from collections import deque

    in_degree = {i: 0 for i in range(1, n + 1)}
    for node in graph:
        for neighbor in graph[node]:
            in_degree[neighbor] += 1

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != n:
        return 'IMPOSSIBLE\n'

    # Convert result to string
    return ' '.join(map(str, result)) + '\n'

