def solution(input_str):
    lines = input_str.strip().split('\n')

    n, m = map(int, lines[0].split())

    original = []
    for i in range(m):
        a, b, e = map(int, lines[1 + i].split())
        original.append((a, b, e, i - 1))

    sorted_edges = sorted(original, key=lambda x: x[2])

    parent = list(range(n + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    mst_indices = set()
    for a, b, e, i in sorted_edges:
        if union(a, b):
            mst_indices.add(i)

    adj = [[] for _ in range(n + 1)]
    edges_list = []
    for a, b, e, i in sorted_edges:
        if i in mst_indices:
            adj[a].append((b, e))
            adj[b].append((a, e))
            edges_list.append((a, b, e))

    LOG = 20
    depth = [0] * (n + 1)
    up = [[0] * LOG for _ in range(n + 1)]
    max_edge_on_parent = [[0] * LOG for _ in range(n + 1)]

    from collections import deque
    queue = deque([1])
    visited = {1}
    depth[1] = 0
    up[1][0] = 1
    max_edge_on_parent[1][0] = 0

    while queue:
        u = queue.popleft()
        for v, w in adj[u]:
            if v not in visited:
                visited.add(v)
                depth[v] = depth[u] + 1
                up[v][0] = u
                max_edge_on_parent[v][0] = w
                queue.append(v)

    for i in range(1, LOG):
        for u in range(n + 1):
            up[u][i] = up[up[u][i-1]][i-1]
            max_edge_on_parent[u][i] = max(max_edge_on_parent[u][i-1], max_edge_on_parent[up[u][i-1]][i-1])

    def query_max_path(u, v):
        res = 0
        if depth[u] < depth[v]:
            u, v = v, u

        for i in range(LOG - 1, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                res = max(res, max_edge_on_parent[u][i])
                u = up[u][i]

        if u != v:
            for i in range(LOG - 1, -1, -1):
                if up[u][i] != up[v][i]:
                    res = max(res, max_edge_on_parent[u][i])
                    res = max(res, max_edge_on_parent[v][i])
                    u = up[u][i]
                    v = up[v][i]
            res = max(res, max_edge_on_parent[u][0])
            res = max(res, max_edge_on_parent[v][0])
        return res

    output = []
    for a, b, e, i in original:
        if i not in mst_indices:
            output.append(str(query_max_path(a, b)))

    return '\n'.join(output)

