def solution(input_data):
    n = int(input_data.strip())

    if n == 0:
        return "0\n"

    visited = {n: 0}
    queue = deque([n])

    while queue:
        curr = queue.popleft()

        digits = set(str(curr))

        for d in digits:
            subtract = int(d)
            next_val = curr - subtract

            if next_val == 0:
                return str(visited[curr] + 1) + "\n"

            if next_val not in visited:
                visited[next_val] = visited[curr] + 1
                queue.append(next_val)

    return "0\n"

